function BrandGradient({ id }: { id: string }) {
  return (
    <defs>
      <linearGradient id={id} x1="0" y1="1" x2="1" y2="0">
        <stop offset="0%" stopColor="#00a3e0" />
        <stop offset="52%" stopColor="#6a2c91" />
        <stop offset="100%" stopColor="#ec1e79" />
      </linearGradient>
    </defs>
  );
}

/** The Orion "O/" mark. Uses the brand gradient by default, or currentColor. */
export function OrionMark({
  className,
  variant = 'gradient',
}: {
  className?: string;
  variant?: 'gradient' | 'current';
}) {
  const gradId = useId();
  const fill = variant === 'gradient' ? `url(#${gradId})` : 'currentColor';
  return (
    <svg
      viewBox="0 0 83.64 53.93"
      role="img"
      aria-label="Orion Innovation"
      className={cn('h-auto', className)}
    >
      {variant === 'gradient' && <BrandGradient id={gradId} />}
      <path d={MARK_RING} fill={fill} fillRule="evenodd" />
      <path d={MARK_SLASH} fill={fill} />
    </svg>
  );
}

/** Full "O/ Orion Innovation" lockup. Mark can be gradient; text is currentColor. */
export function OrionLogo({
  className,
  gradientMark = false,
}: {
  className?: string;
  gradientMark?: boolean;
}) {
  const gradId = useId();
  const markFill = gradientMark ? `url(#${gradId})` : 'currentColor';
  return (
    <svg
      viewBox="0 0 244.84 53.93"
      role="img"
      aria-label="Orion Innovation"
      className={cn('h-auto', className)}
    >
      {gradientMark && <BrandGradient id={gradId} />}
      <path d={WORDMARK_TEXT} fill="currentColor" />
      <path d={WORDMARK_TM} fill="currentColor" />
      <path d={MARK_SLASH} fill={markFill} />
      <path d={MARK_RING} fill={markFill} fillRule="evenodd" />
    </svg>
  );
}

export const OI_TAGLINE = "Envision what's next. Build what matters.";
